mapper.select:
select *
from t_order_info
where id = (
    select id
    from (
        select id
        from t_order_info
        where product_id = #{productId}
          and payment_type = #{paymentType}
          and order_status = #{orderStatus}


                  and payment_app_id = #{paymentAppId}


                  and payment_app_id is null


        order by create_time desc, id desc
    ) latest_order
    where rownum <= 1
)
for update
